<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipUserVO;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipRelyingPartyVO;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipTrustedClientVO;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipGroupsVO;
use Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject\UserGroupMembershipVersionVO;
use Civi\Lughauth\Features\Access\UserGroupMembership\Application\Usecase\Create\UserGroupMembershipCreateParams;
use PHPUnit\Framework\TestCase;

final class UserGroupMembershipCreateParamsUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new UserGroupMembershipCreateParams();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrCurrent(UserGroupMembershipUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrCurrent(UserGroupMembershipUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrCurrent(UserGroupMembershipUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrCurrent(UserGroupMembershipUserVO::from($userOtherValue))->value());
        $relyingPartyOneValue = new RelyingPartyRef('one');
        $relyingPartyOtherValue = new RelyingPartyRef('other');
        $copy = $value->relyingParty($relyingPartyOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingParty());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingParty());
        $this->assertEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrCurrent(UserGroupMembershipRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrCurrent(UserGroupMembershipRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $value->unsetRelyingParty();
        $this->assertEquals(new RelyingPartyRef('other'), $value->getRelyingPartyOrCurrent(UserGroupMembershipRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $this->assertNotEquals(new RelyingPartyRef('one'), $value->getRelyingPartyOrCurrent(UserGroupMembershipRelyingPartyVO::from($relyingPartyOtherValue))->value());
        $trustedClientOneValue = new TrustedClientRef('one');
        $trustedClientOtherValue = new TrustedClientRef('other');
        $copy = $value->trustedClient($trustedClientOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClient());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClient());
        $this->assertEquals(new TrustedClientRef('one'), $value->getTrustedClientOrCurrent(UserGroupMembershipTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('other'), $value->getTrustedClientOrCurrent(UserGroupMembershipTrustedClientVO::from($trustedClientOtherValue))->value());
        $value->unsetTrustedClient();
        $this->assertEquals(new TrustedClientRef('other'), $value->getTrustedClientOrCurrent(UserGroupMembershipTrustedClientVO::from($trustedClientOtherValue))->value());
        $this->assertNotEquals(new TrustedClientRef('one'), $value->getTrustedClientOrCurrent(UserGroupMembershipTrustedClientVO::from($trustedClientOtherValue))->value());
        $groupsOneValue = 'one';
        $groupsOtherValue = 'other';
        $copy = $value->groups($groupsOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getGroups());
        $this->assertNotEquals('other', $value->getGroups());
        $this->assertEquals('one', $value->getGroupsOrCurrent(UserGroupMembershipGroupsVO::from($groupsOtherValue))->value());
        $this->assertNotEquals('other', $value->getGroupsOrCurrent(UserGroupMembershipGroupsVO::from($groupsOtherValue))->value());
        $value->unsetGroups();
        $this->assertEquals('other', $value->getGroupsOrCurrent(UserGroupMembershipGroupsVO::from($groupsOtherValue))->value());
        $this->assertNotEquals('one', $value->getGroupsOrCurrent(UserGroupMembershipGroupsVO::from($groupsOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(UserGroupMembershipVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(UserGroupMembershipVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(UserGroupMembershipVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(UserGroupMembershipVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
